/* EnergyLab PRO 3.0 — Oficina de competências, alinhada à UC de 16 horas.
   Persistência local, entradas validadas, cálculo determinístico, evidências. */
(function(){
'use strict';
const E=window.ELab.projectEngine;
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=E.number,money=E.money;
const storageKey='energylab-pro-oficina-uc16-v3';
let project=load(),current='trilha',lastIssue='',renderCount=0;
const tabs={trilha:['Visão geral','16h'],vistoria:['Levantamento técnico','3h'],dimensionamento:['Dimensionamento FV','4h'],diagrama:['Diagrama unifilar','1h'],seguranca:['Segurança e normas','1h'],comissionamento:['Comissionamento','2h'],economia:['Viabilidade','1h'],relatorio:['Dossiê e avaliação','4h']};
const stages=[['Fundamentos e integração',2,'Aprender','Conteúdos: renováveis, sistemas on-grid/off-grid, agentes e grandezas.','learn'],['Levantamento técnico e concessionária',3,'Vistoria','Fatura, requisitos do cliente e infraestrutura.','vistoria'],['Dimensionamento e documentação',4,'Dimensionamento + diagrama','Strings, MPPT, perdas e documentação.','dimensionamento'],['Segurança, instalação e comissionamento',3,'Segurança + ensaios','Conformidade, inspeção, testes e registros.','seguranca'],['Situação de aprendizagem final',4,'Relatório técnico','Apresentar solução fundamentada para uma indústria fictícia.','relatorio']];
function load(){let p=E.defaults();try{const raw=JSON.parse(localStorage.getItem(storageKey)||'null');if(raw&&typeof raw==='object'){
  for(const group of ['site','pv','inverter','economics','meta'])if(raw[group]&&typeof raw[group]==='object')Object.keys(p[group]).forEach(k=>{if(Object.hasOwn(raw[group],k)&&typeof raw[group][k]===typeof p[group][k])p[group][k]=raw[group][k];});
  for(const group of ['safety','docs','commission'])if(raw[group]&&typeof raw[group]==='object')p[group]=structuredClone(raw[group]);
  if(Array.isArray(raw.loads))p.loads=raw.loads.filter(l=>l&&typeof l.name==='string').slice(0,35).map(l=>({id:String(l.id||Date.now()).slice(0,60),name:l.name.slice(0,100),qty:Number(l.qty),w:Number(l.w),h:Number(l.h),days:Number(l.days)}));
  if(typeof raw.diagramReviewed==='boolean')p.diagramReviewed=raw.diagramReviewed;
}}catch(e){console.warn('Projeto anterior inválido; carregado modelo inicial.',e)}return p;}
function save(){try{project.meta.updatedAt=new Date().toISOString();localStorage.setItem(storageKey,JSON.stringify(project));}catch(e){notify('O navegador não permitiu salvar os dados. Exporte o projeto JSON.');}summary();}
function notify(m){if(window.EnergyLabBridge)window.EnergyLabBridge.toast(m);else alert(m);}
function wrap(title,sub,body){return `<div class="v3-panel-heading"><div><div class="eyebrow">OFICINA DE PROJETOS / ${esc(title).toUpperCase()}</div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div></div>${lastIssue?`<div class="v3-alert bad" role="alert">${esc(lastIssue)}</div>`:''}${body}`;}
function card(title,body,extra=''){return `<section class="v3-card ${extra}"><h3>${title}</h3>${body}</section>`;}
function metric(title,value,sub='',tone='blue'){return `<div class="v3-metric ${tone}"><span>${esc(title)}</span><strong>${value}</strong><small>${sub}</small></div>`;}
function info(s){return `<div class="v3-infobox">${s}</div>`;}
function input(path,label,unit,min,max,step=1,tip=''){const parts=path.split('.');let target=project;for(const part of parts)target=target[part];const id='work-'+path.replaceAll('.','-');return `<div class="v3-field"><label for="${id}">${esc(label)}</label><div class="v3-inputunit"><input id="${id}" type="number" inputmode="decimal" data-workfield="${path}" min="${min}" max="${max}" step="${step}" value="${esc(target)}" required/><span>${esc(unit)}</span></div>${tip?`<small>${esc(tip)}</small>`:''}</div>`;}
function textinput(path,label,help='',textarea=false){let target=project;for(const part of path.split('.'))target=target[part];const id='work-'+path.replaceAll('.','-');return `<div class="v3-field"><label for="${id}">${esc(label)}</label>${textarea?`<textarea id="${id}" data-worktext="${path}" rows="3" maxlength="900">${esc(target)}</textarea>`:`<input id="${id}" type="text" data-worktext="${path}" maxlength="180" value="${esc(target)}"/>`}${help?`<small>${esc(help)}</small>`:''}</div>`;}
function select(path,label,options,help=''){let target=project;for(const part of path.split('.'))target=target[part];return `<div class="v3-field"><label for="work-${path}">${esc(label)}</label><select id="work-${path}" data-workselect="${path}">${options.map(([val,l])=>`<option value="${esc(val)}" ${target===val?'selected':''}>${esc(l)}</option>`).join('')}</select>${help?`<small>${esc(help)}</small>`:''}</div>`;}
function button(action,label,variant='primary'){return `<button type="button" class="btn btn-${variant} btn-small" data-workaction="${action}">${label}</button>`;}
function calcMessages(calc){return `<div class="v3-flags">${calc.errors.map(x=>`<div class="v3-alert bad" role="status">✕ ${esc(x)}</div>`).join('')}${calc.warnings.map(x=>`<div class="v3-alert warn">▲ ${esc(x)}</div>`).join('')}${calc.valid?'<div class="v3-alert good">✓ Os limites didáticos informados estão consistentes entre si. Isso não comprova conformidade normativa.</div>':''}</div>`;}
function summary(){const p=E.assessment(project),t=$('v3-completion'),b=$('v3-completion-bar');if(t)t.textContent=`${p.done} / ${p.total}`;if(b)b.style.width=`${100*p.done/p.total}%`;}
function show(tab,focus=false){if(!tabs[tab])return;current=tab;lastIssue='';document.querySelectorAll('[data-worktab]').forEach(btn=>{const active=btn.dataset.worktab===tab;btn.classList.toggle('selected',active);btn.setAttribute('aria-selected',String(active));btn.tabIndex=active?0:-1;});render();if(focus)$('workbench-content').scrollIntoView({behavior:'auto',block:'start'});}
function render(){const target=$('workbench-content');if(!target)return;renderCount++;let out='';switch(current){case 'trilha':out=renderTrail();break;case 'vistoria':out=renderSite();break;case 'dimensionamento':out=renderPV();break;case 'diagrama':out=renderDiagram();break;case 'seguranca':out=renderSafety();break;case 'comissionamento':out=renderCommission();break;case 'economia':out=renderEconomics();break;case 'relatorio':out=renderReport();break;}target.innerHTML=out;summary();}
function renderTrail(){const a=E.assessment(project);return wrap('Trilha profissional de 16 horas','Acompanhamento orientado por capacidades: padrão 1.1 (cliente), 1.2 (procedimentos e segurança), 1.3 (solução técnica).',`
<div class="v3-hero-case"><div><div class="v3-label">SITUAÇÃO DE APRENDIZAGEM</div><h3>Missão: implantar geração renovável em uma indústria</h3><p>Você integra a equipe técnica da empresa fictícia Amazônia Energia Engenharia. Um cliente industrial necessita de um estudo de integração de sistema fotovoltaico, com documentação, verificação de segurança e análise da viabilidade.</p><div class="v3-actions">${button('start','Começar levantamento →')}${button('example','Restaurar exemplo didático','outline')}</div></div><div class="v3-hero-stats">${metric('Consumo do cliente',`${fmt(project.site.consumption,0)} kWh/mês`,'Fatura fictícia')}${metric('Área útil',`${fmt(project.site.usable,0)} m²`,'Disponível após restrições','green')}${metric('Etapas verificadas',`${a.done} / 7`,'Registro local','orange')}</div></div>
<div class="v3-section-title"><h3>Jornada em sala e laboratório</h3><span>16 horas · cinco momentos curriculares</span></div>
<div class="v3-journey">${stages.map((x,i)=>`<div class="v3-journey-item"><div class="v3-step-num">${String(i+1).padStart(2,'0')}</div><div><strong>${esc(x[0])}</strong><p>${esc(x[3])}</p><small>${esc(x[2])}</small></div><div class="v3-step-side"><strong>${x[1]}h</strong>${button('tab:'+x[4],'Abrir →','outline')}</div></div>`).join('')}</div>
<div class="v3-section-title"><h3>Competências em evidência</h3><span>Concluídas somente após validação ou registro</span></div>
<div class="v3-status-grid">${[['vistoria','1. Levantamento'],['dimensionamento','2. Projeto elétrico FV'],['diagrama','3. Diagrama'],['seguranca','4. Segurança'],['comissionamento','5. Comissionamento'],['economia','6. Viabilidade'],['relatorio','7. Relatório']].map(([k,label])=>`<button class="v3-status-tile ${a.goals[k]?'done':''}" data-workaction="tab:${k}"><span>${a.goals[k]?'✓':'○'}</span><strong>${label}</strong><small>${a.goals[k]?'Critério atendido':'Pendente'}</small></button>`).join('')}</div>
${card('Fontes renováveis além de solar e eólica',`<div class="v3-source-grid">${[['Hidrelétrica','Potencial hidráulico e vazão, regime hídrico e impactos ambientais.'],['Biomassa','Resíduos, disponibilidade do combustível, logística e eficiência térmica.'],['Geotérmica','Gradiente térmico e recursos geológicos locais.'],['Maremotriz','Variação das marés, sítios adequados e efeitos ambientais.'],['Células a combustível','Convertem energia química em eletricidade; o caráter renovável depende da origem do combustível.']].map(([h,d])=>`<div class="v3-source"><strong>${h}</strong><p>${d}</p></div>`).join('')}</div><p class="v3-fine">O dimensionamento executivo dessas fontes não integra o modelo numérico desta versão. A ementa aborda seus fundamentos.</p>`)}
${info('<strong>Orientação ao docente:</strong> utilize os momentos de abertura/contextualização, exposição dialogada e prática em laboratório em cada etapa. O simulador representa situações didáticas e não substitui bancada, instrumentos nem documentação normativa.')}`);}
function renderSite(){const c=E.siteCalc(project);return wrap('1 · Levantamento técnico','Padrão 1.1 — conhecer o cliente, interpretar os dados de campo e identificar a infraestrutura e requisitos de conexão.',`
<div class="v3-two"><div class="v3-stack">
${card('Ficha do cliente e do imóvel',`<div class="v3-form-grid">${textinput('site.client','Cliente / empreendimento','Use um cliente fictício.')}${textinput('site.city','Município / local')}${select('site.segment','Categoria',['industrial','comercial','residencial','rural'].map(x=>[x,x.charAt(0).toUpperCase()+x.slice(1)]))}${select('site.connection','Tipo de integração',[['grid','Conectado à rede'],['island','Isolado (off-grid)']])}${textinput('site.supply','Tensão / padrão disponível','Valor declarado, ainda não verificado.')}</div>`)}
${card('Medições e condicionantes do local',`<div class="v3-form-grid">${input('site.consumption','Consumo na fatura','kWh/mês',1,1000000,1)}${input('site.roof','Área total disponível','m²',1,500000,.1)}${input('site.usable','Área útil para módulos','m²',1,500000,.1,'Desconte acessos, obstáculos e recuos de projeto.')}${input('site.shade','Sombreamento estimado','%',0,100,1)}${input('site.hsp','Horas de sol pleno — HSP','h/dia',.1,10,.1,'Valor manual didático; verificar base solarimétrica confiável.')}${input('site.tariff','Tarifa ilustrativa','R$/kWh',.01,10,.01,'Não inclui necessariamente tributos, demanda ou compensações.')}</div><div class="v3-section-title"><h3>Leitura do sistema tarifário</h3></div><div class="v3-form-grid">${select('site.tariffClass','Classificação de atendimento',[["A","Grupo A (referência)"],["B","Grupo B (referência)"]])}${select('site.tariffType','Modalidade ilustrativa',[["convencional","Convencional"],["horaria","Horária (ponta / fora ponta)"]])}${input('site.peakKWh','Consumo na ponta','kWh/mês',0,1000000,1)}${input('site.offPeakKWh','Consumo fora da ponta','kWh/mês',0,1000000,1)}${input('site.contractedKW','Demanda contratada','kW',0,1000000,1)}${input('site.demandPrice','Tarifa de demanda (referência)','R$/kW',0,1000,.1)}</div><p class="v3-fine">Dados de ponta, fora de ponta e demanda servem para leitura de fatura e classificação; a simulação econômica adota tarifa de energia única e não calcula faturamento horário ou demanda contratada.</p>${textinput('site.gridComments','Observações técnicas / requisitos de conexão','Informe exigências a verificar, não declare homologação.',true)}`)}
</div><div class="v3-stack">
${card('Painel de vistoria',`<div class="v3-kpis">${metric('Consumo levantado',`${fmt(c.monthlyLoad,1)} kWh`,'Soma das cargas','green')}${metric('Potência conectada',`${fmt(c.connectedKW,2)} kW`,'Não é demanda medida')}${metric('Diferença da fatura',`${fmt(c.difference,1)} kWh`,'Cargas − consumo declarado','orange')}</div><div class="v3-brief"><strong>Verificação do técnico</strong><p>${Math.abs(c.difference)>project.site.consumption*.20?'Há diferença superior a 20% entre o quadro estimado e a fatura fictícia. Revise horas, dias e equipamentos.':'O quadro de cargas e a fatura estão relativamente próximos no exercício. Confirme medições e regimes de operação reais.'}</p></div>${c.problems.map(x=>`<div class="v3-alert bad">${esc(x)}</div>`).join('')}`)}
${card('Checklist da visita',`<div class="v3-checklist"><p>Conferir acesso, orientação, sombra, estrutura, quadro elétrico, padrão de entrada, disponibilidade de espaço e documentação da concessionária.</p><p><strong>Evidência esperada:</strong> ficha de vistoria, fotos simuladas e quadro de cargas. Nunca considere os dados fictícios como levantamento real.</p></div><div class="v3-actions">${button('validate:site','✓ Validar levantamento')}${button('tab:dimensionamento','Ir para dimensionamento →','outline')}</div>`)}
</div></div>
${card('Quadro de cargas editável',`<div class="v3-table-scroll"><table class="v3-table"><thead><tr><th>Equipamento / carga</th><th>Qtd.</th><th>Potência unit.</th><th>Uso diário</th><th>Dias/mês</th><th>Energia</th><th></th></tr></thead><tbody>${project.loads.map(l=>{const k=l.qty*l.w*l.h*l.days/1000;return `<tr><td><input aria-label="Nome da carga" type="text" maxlength="100" value="${esc(l.name)}" data-load="${esc(l.id)}" data-loadprop="name"/></td>${[['qty','un',1],['w','W',50],['h','h',.5],['days','dias',1]].map(([key,unit,step])=>`<td><div class="v3-rowfield"><input type="number" min="0" max="${key==='h'?24:key==='days'?31:key==='qty'?10000:1000000}" step="${step}" value="${esc(l[key])}" data-load="${esc(l.id)}" data-loadprop="${key}" aria-label="${key}: ${esc(l.name)}"/><small>${unit}</small></div></td>`).join('')}<td><strong>${fmt(k,1)} kWh</strong></td><td><button class="v3-rowremove" type="button" aria-label="Remover ${esc(l.name)}" data-workaction="remove:${esc(l.id)}">×</button></td></tr>`}).join('')}</tbody><tfoot><tr><th colspan="5">Consumo estimado das cargas</th><th colspan="2">${fmt(c.monthlyLoad,1)} kWh/mês</th></tr></tfoot></table></div><div class="v3-actions">${button('addload','＋ Adicionar carga','outline')}<span class="v3-fine">E = quantidade × potência (W) × horas/dia × dias/mês ÷ 1000.</span></div>`)}
`);}
function renderPV(){const d=E.solarCalc(project);const options=Object.entries(E.panelPresets).map(([k,v])=>[k,`${v.panel} · exemplo`]);return wrap('2 · Dimensionamento fotovoltaico','Padrões 1.1 e 1.3 — arranjos CC, inversores, perdas, área, tensão a frio, MPPT e corrente por entrada.',`
<div class="v3-two"><div class="v3-stack">
${card('Módulo e dados de referência',`<div class="v3-field"><label for="v3-preset">Selecionar módulo didático</label><select id="v3-preset" data-preset="true"><option value="custom">Dados editáveis</option>${options.map(([k,label])=>`<option value="${k}" ${project.pv.wp===E.panelPresets[k].wp?'selected':''}>${esc(label)}</option>`).join('')}</select><small>Perfis fictícios para ensino — substitua por datasheet verdadeiro quando disponível.</small></div><div class="v3-form-grid">${input('pv.wp','Potência STC','Wp',1,1500,1)}${input('pv.area','Área por módulo','m²',.1,10,.01)}${input('pv.voc','Tensão circuito aberto Voc','V',1,300,.1)}${input('pv.vmp','Tensão de máxima potência Vmp','V',1,300,.1)}${input('pv.isc','Corrente de curto Isc','A',.1,100,.01)}${input('pv.imp','Corrente em MPP Imp','A',.1,100,.01)}${input('pv.betaVoc','Coeficiente Voc','%/°C',-1,-.01,.01)}${input('pv.betaVmp','Coeficiente Vmp','%/°C',-1,-.01,.01)}</div>`)}
${card('Associação e rendimento',`<div class="v3-form-grid">${input('pv.series','Módulos em série por string','un',1,60,1)}${input('pv.parallel','Strings em paralelo','un',1,60,1)}${input('pv.tMin','Temperatura mínima de projeto','°C',-40,80,1)}${input('pv.tCellMax','Temperatura máxima da célula','°C',0,110,1)}${input('pv.pr','Performance ratio PR','fração',.1,1,.01,'PR global e sombreamento tratados separadamente.')}${input('site.hsp','HSP de referência','h/dia',.1,10,.1)}</div>`)}
${card('Inversor e limites elétricos',`<div class="v3-form-grid">${input('inverter.acKW','Potência nominal CA','kW',.5,100,.5)}${input('inverter.maxDC','Tensão CC máxima','V',20,2000,10)}${input('inverter.mpptMin','MPPT mínimo','V',20,1500,10)}${input('inverter.mpptMax','MPPT máximo','V',20,1800,10)}${input('inverter.mpptA','Corrente máxima MPPT','A',.1,200,.1)}${input('inverter.maxIscA','Isc máxima por entrada MPPT','A',.1,250,.1)}${input('inverter.mpptCount','Quantidade de MPPT','un',1,30,1)}${input('inverter.eff','Eficiência CA nominal','fração',.5,1,.01)}</div><p class="v3-fine">Assume distribuição equilibrada de strings entre MPPTs. Verificar entradas efetivas, limites de conectores, projeto CC e curvas reais do fabricante.</p>`)}
</div><div class="v3-stack">
${card('Resultado do arranjo',`<div class="v3-kpis">${metric('Módulos / strings',`${d.modules} / ${project.pv.parallel}`,'Unidades totais','green')}${metric('Potência CC',`${fmt(d.dcWp/1000,2)} kWp`,'Condição STC')}${metric('Produção mensal',`${fmt(d.monthlyKWh,0)} kWh`,'Estimativa, 30 dias','orange')}${metric('Uso da área',`${fmt(d.area,1)} / ${fmt(project.site.usable,1)} m²`,'Módulos / útil')}${metric('Voc corrigida a frio',`${fmt(d.vocCold,1)} V`,'Conferir máximo CC')}${metric('Vmp em célula quente',`${fmt(d.vmpHot,1)} V`,'Conferir mínimo MPPT')}${metric('Imp por MPPT',`${fmt(d.mpptImp,2)} A`,'String(s) por MPPT')}${metric('Razão CC/CA',fmt(d.dcAc,2),'Não garante ausência de clipping')}</div>${calcMessages(d)}<div class="v3-actions">${button('validate:pv','✓ Verificar dimensionamento')}${button('apply-sim','↗ Testar no simulador','outline')}</div>`)}
${card('Memória de cálculo explicada',`<div class="v3-math"><p><strong>1. Potência STC</strong></p><code>P<sub>CC</sub> = N<sub>série</sub> × N<sub>paralelo</sub> × P<sub>módulo</sub></code><p>${project.pv.series} × ${project.pv.parallel} × ${fmt(project.pv.wp,0)} Wp = <b>${fmt(d.dcWp/1000,2)} kWp</b></p><p><strong>2. Tensão a frio (critério CC)</strong></p><code>Voc(T) = N<sub>série</sub> × Voc<sub>STC</sub> × [1 + βVoc × (T<sub>min</sub> − 25)]</code><p>βVoc = ${fmt(project.pv.betaVoc,2)} %/°C = ${fmt(project.pv.betaVoc/100,4)} /°C. Resultado: <b>${fmt(d.vocCold,1)} V</b>.</p><p><strong>3. MPPT na temperatura alta</strong></p><code>Vmp(T) = N<sub>série</sub> × Vmp<sub>STC</sub> × [1 + βVmp × (T<sub>célula</sub> − 25)]</code><p>Resultado: <b>${fmt(d.vmpHot,1)} V</b>; janela informada: ${fmt(project.inverter.mpptMin,0)}–${fmt(project.inverter.mpptMax,0)} V.</p><p><strong>4. Corrente máxima por MPPT (aproximação)</strong></p><code>I<sub>MPP</sub> = I<sub>mp,módulo</sub> × strings/MPPT</code><p>${fmt(project.pv.imp,2)} × ${d.stringsPerMppt} = <b>${fmt(d.mpptImp,2)} A</b>.</p><p><strong>5. Energia mensal estimada</strong></p><code>E = (P<sub>CC</sub> / 1000) × HSP × PR × (1 − sombreamento) × 30</code><p>${fmt(d.dcWp/1000,2)} kWp × ${fmt(project.site.hsp,1)} h × ${fmt(project.pv.pr,2)} × (1 − ${fmt(project.site.shade,0)}%) × 30 = <b>${fmt(d.monthlyKWh,0)} kWh/mês</b>.</p></div><p class="v3-fine">Não modela radiação horária, orientação, temperatura anual, degradação, clipping detalhado, mismatch, curva IV ou disponibilidade. PR global não deve receber perdas duplicadas. O modelo simplificado não gera projeto executivo.</p>`)}
${card('Conecte suas decisões',`<p>Uma combinação de strings pode ser eletricamente adequada, mas inviável pela área. Compare o resultado com o levantamento técnico e justifique uma solução parcial quando necessário.</p><div class="v3-actions">${button('tab:diagrama','Montar diagrama →')}${button('tab:economia','Analisar retorno','outline')}</div>`)}
</div></div>`);}
function renderDiagram(){const d=E.solarCalc(project),island=project.site.connection==='island',mode=island?'ISOLADO / OFF-GRID':'CONECTADO / ON-GRID';return wrap('3 · Diagrama unifilar didático','Padrões 1.2 e 1.3 — reconhecer componentes, simbologias e fluxo elétrico. Esquema funcional não é desenho executivo.',`
<div class="v3-two"><div class="v3-stack">
${card('Topologia e componentes',`<div class="v3-form-grid">${select('site.connection','Arquitetura',[['grid','Conectada à rede'],['island','Isolada com armazenamento (conceitual)']])}${input('pv.series','Módulos por string','un',1,60,1)}${input('pv.parallel','Strings em paralelo','un',1,60,1)}</div><div class="v3-brief"><strong>Como interpretar:</strong><p>Linhas contínuas representam conexões elétricas conceituais; dispositivos DC e CA são identificados por suas funções. A topologia real, aterramento, seccionamento e proteções dependem do projeto e de normas aplicáveis.</p></div><div class="v3-actions">${button('download-svg','↓ Exportar SVG','outline')}${button('mark-diagram','✓ Registrei a interpretação')}</div>`)}
${card('Revisão de símbolos',`<div class="v3-glossary"><div><b>FV</b><p>Arranjo fotovoltaico: gera corrente contínua (CC).</p></div><div><b>CC</b><p>Seccionamento e proteção do circuito CC — seleção conforme projeto.</p></div><div><b>INV</b><p>Inversor: converte potência CC em CA e executa funções de controle.</p></div><div><b>CA</b><p>Quadro e proteção em corrente alternada.</p></div><div><b>MED</b><p>Medição e interface com o ponto de conexão, quando aplicável.</p></div><div><b>BAT</b><p>Armazenamento requer conversor/controlador compatível.</p></div></div>`)}
</div><div class="v3-stack">
${card('Diagrama atualizado pelas entradas',`<div class="v3-diagram-top"><span>${mode}</span><span>${d.modules} módulos · ${fmt(d.dcWp/1000,2)} kWp</span></div><div class="v3-diagram-scroll"><svg id="v3-singleline" xmlns="http://www.w3.org/2000/svg" width="760" height="390" viewBox="0 0 760 390" role="img" aria-label="Diagrama unifilar didático do sistema ${mode}"><defs><marker id="v3-arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0 6 3 0 6" fill="none" stroke="#68bcff" stroke-width="1.2"/></marker></defs>
<rect x="8" y="8" width="744" height="374" rx="15" fill="#09182c" stroke="#2e5274"/><g stroke="#4f85bc" stroke-width="2.5" fill="none" stroke-linejoin="round" marker-end="url(#v3-arrow)"><path d="M139 125 H208"/><path d="M329 125 H378"/><path d="M499 125 H552"/><path d="M618 158 V207"/>${!island?'<path d="M618 270 V299 H475"/>':'<path d="M618 270 V299 H485"/>'}</g>
<g fill="#152d4b" stroke="#62aef0" stroke-width="2"><rect x="30" y="86" rx="10" width="109" height="78"/><rect x="208" y="86" rx="10" width="121" height="78"/><rect x="378" y="86" rx="10" width="121" height="78"/><rect x="552" y="86" rx="10" width="132" height="78"/><rect x="552" y="207" rx="10" width="132" height="63"/><rect x="355" y="298" rx="10" width="130" height="62"/></g>
<g fill="#e9f7ff" font-family="Arial, sans-serif" font-size="15" font-weight="bold" text-anchor="middle"><text x="84" y="116">FV</text><text x="84" y="137" font-size="11">${d.modules} módulos</text><text x="268" y="113">CC</text><text x="268" y="136" font-size="10">Proteções</text><text x="438" y="113">INV</text><text x="438" y="135" font-size="11">${fmt(project.inverter.acKW,1)} kW CA</text><text x="618" y="113">CA</text><text x="618" y="135" font-size="11">Quadro</text><text x="618" y="244">CARGAS</text><text x="420" y="327">${island?'BAT / EMS':'MED / REDE'}</text><text x="420" y="344" font-size="10">${island?'Armazenamento':'Interface de conexão'}</text></g>
<g fill="#a5bfdc" font-size="11" font-family="Arial,sans-serif"><text x="72" y="184" text-anchor="middle">${project.pv.series}S × ${project.pv.parallel}P</text><text x="265" y="184" text-anchor="middle">String DC</text><text x="438" y="184" text-anchor="middle">CC → CA</text><text x="615" y="184" text-anchor="middle">Instalação CA</text></g>
${island?'<g stroke="#f3b76b" stroke-width="2" fill="none" stroke-dasharray="6 6"><path d="M354 330 H300 V150 H378"/></g>':'<g stroke="#4ec8bb" stroke-width="2" fill="none" stroke-dasharray="6 6"><path d="M355 330 H301 V345 H198"/></g>'}<text x="35" y="40" fill="#78b1de" font-size="12" font-family="Arial">FLUXO DE ENERGIA • ILUSTRAÇÃO FUNCIONAL</text><text x="30" y="374" fill="#94aeca" font-size="10" font-family="Arial">Não representa esquema de proteção, aterramento, isolação e cabos de uma instalação real.</text></svg></div>${d.errors.length?`<div class="v3-alert bad">O diagrama representa as entradas atuais, mas o dimensionamento possui ${d.errors.length} incompatibilidade(s).</div>`:'<div class="v3-alert good">Diagrama gerado com as informações atualmente inseridas.</div>'}<p class="v3-fine">No sistema isolado, a bateria e sua interface são mostradas apenas de modo conceitual: compatibilidade, controladores, autonomia e proteções exigem projeto específico.</p>`)}
</div></div>`);}
function renderSafety(){const done=E.safetyQuestions.filter(q=>project.safety[q.id]).length;return wrap('4 · Segurança, normas e sustentabilidade','Padrão 1.2 — desenvolver o julgamento técnico, sem substituir procedimentos de trabalho ou normas vigentes.',`
<div class="v3-two"><div class="v3-stack">
${card('Checklist técnico de pré-implantação',`<p class="v3-fine">Marque apenas os requisitos efetivamente analisados no exercício. Itens desmarcados são pendências, não aprovações tácitas.</p><div class="v3-checks">${E.safetyQuestions.map((q,i)=>`<label class="v3-check-row"><input type="checkbox" data-safety="${q.id}" ${project.safety[q.id]?'checked':''}/><span><strong>${String(i+1).padStart(2,'0')} · ${esc(q.text)}</strong><small>${esc(q.detail)}</small></span></label>`).join('')}</div>`)}
</div><div class="v3-stack">
${card('Conformidade em construção',`${metric('Critérios analisados',`${done} / ${E.safetyQuestions.length}`,'Confirmações registradas','orange')}<p>Documente os pontos pendentes antes de elaborar sua entrega final.</p>${done<E.safetyQuestions.length?`<div class="v3-alert warn">${E.safetyQuestions.length-done} requisito(s) ainda não analisado(s) no exercício.</div>`:'<div class="v3-alert good">Todos os itens didáticos foram assinalados. A conformidade real ainda deve ser verificada por responsável habilitado.</div>'}<div class="v3-actions">${button('validate:safety','✓ Validar checklist')}${button('tab:comissionamento','Ir ao comissionamento →','outline')}</div>`)}
${card('Documentos a conferir para conexão à rede',`<p class="v3-fine">Lista de conferência orientativa, <strong>não é lista universal de documentos obrigatórios</strong>. Verifique o padrão e modalidade na distribuidora. No sistema estritamente isolado, critérios de conexão à rede podem não se aplicar.</p><div class="v3-checks">${E.documentItems.map(q=>`<label class="v3-check-row"><input type="checkbox" data-doc="${q.id}" ${project.docs[q.id]?'checked':''}/><span><strong>${esc(q.text)}</strong><small>${esc(q.detail)}</small></span></label>`).join('')}</div><p class="v3-fine">${E.documentItems.filter(q=>project.docs[q.id]).length} de ${E.documentItems.length} itens conferidos no exercício.</p>`)}
${card('Biblioteca de referências institucionais',`<ul class="v3-links"><li><a href="https://www.gov.br/aneel/pt-br/assuntos/geracao/geracao-distribuida" target="_blank" rel="noopener noreferrer">ANEEL — Geração distribuída ↗</a><small>Conferir regras e condições atuais de conexão.</small></li><li><a href="https://www.energisa.com.br/" target="_blank" rel="noopener noreferrer">Concessionária — Energisa ↗</a><small>Consultar padrões e documentação específicos da área de atendimento.</small></li><li><a href="https://www.gov.br/trabalho-e-emprego/pt-br/assuntos/inspecao-do-trabalho/seguranca-e-saude-no-trabalho/normas-regulamentadoras" target="_blank" rel="noopener noreferrer">MTE — Normas Regulamentadoras ↗</a><small>Consultar a redação vigente da NR-10 e demais requisitos.</small></li><li><a href="https://www.abntcatalogo.com.br/" target="_blank" rel="noopener noreferrer">ABNT — Catálogo normativo ↗</a><small>Consultar versões vigentes de normas técnicas aplicáveis.</small></li></ul><p class="v3-fine">Links externos requerem internet. O aplicativo e os exercícios permanecem offline.</p>`)}
${card('Questão de reflexão',`<p>Por que a corrente contínua de um arranjo FV merece atenção mesmo quando a alimentação da rede foi interrompida?</p><div class="v3-actions">${button('hint:safety','Ver orientação progressiva','outline')}</div><div class="v3-hint" id="v3-safety-hint" aria-live="polite">Discuta fontes remanescentes de energia e seccionamento.</div>`)}
</div></div>`);}
function renderCommission(){const calc=E.solarCalc(project),c=project.commission;const caseInfo=E.faultCases[c.fault];return wrap('5 · Comissionamento virtual','Padrão 1.2 — interpretar leituras, confirmar procedimentos e registrar evidências. Não orienta testes em equipamentos energizados.',`
<div class="v3-two"><div class="v3-stack">
${card('Sequência documental e ensaios simulados',`<p>Os valores exibidos são calculados a partir dos dados didáticos, não medidos. Ensaios reais exigem plano de teste, instrumentos, segurança e pessoal autorizado.</p><div class="v3-checks">${E.commissioningSteps.map((x,i)=>`<label class="v3-check-row"><input type="checkbox" data-commission="${x.id}" ${c.steps[x.id]?'checked':''}/><span><strong>${String(i+1).padStart(2,'0')} · ${esc(x.text)}</strong></span></label>`).join('')}</div>`)}
${card('Instrumentos virtuais — resultados teóricos',`<div class="v3-instruments">${metric('Voltímetro CC · Voc frio',`${fmt(calc.vocCold,1)} V`,'Exemplo sem carga')}${metric('Tensão MPPT quente',`${fmt(calc.vmpHot,1)} V`,'Condição didática','green')}${metric('Corrente por MPPT',`${fmt(calc.mpptImp,2)} A`,'Agregação de strings')}${metric('Potência nominal arranjo',`${fmt(calc.dcWp/1000,2)} kWp`,'STC','orange')}</div>${calc.errors.length?`<div class="v3-alert bad">Há incompatibilidades a corrigir no dimensionamento: ${calc.errors.length} ocorrência(s).</div>`:'<div class="v3-alert good">Os limites dimensionados foram verificados neste modelo simplificado.</div>'}`)}
</div><div class="v3-stack">
${card('Diagnóstico de falhas — cenário guiado',`${select('commission.fault','Falha didática',[['shading','Sombreamento parcial'],['polarity','Polaridade invertida'],['mppt','Tensão fora de MPPT'],['open','String interrompida']])}<div class="v3-fault"><span>CENÁRIO</span><h4>${esc(caseInfo.title)}</h4><p>${esc(caseInfo.data)}</p></div><div class="v3-field"><label for="v3-fault-answer">Qual hipótese melhor explica a leitura?</label><select id="v3-fault-answer" data-workselect="commission.answer"><option value="" ${!c.answer?'selected':''}>Selecione uma hipótese</option>${[['open','Interrupção de string'],['shadow','Sombreamento desigual'],['polarity','Conexão com polaridade invertida'],['mppt','Incompatibilidade de faixa MPPT']].map(([v,t])=>`<option value="${v}" ${c.answer===v?'selected':''}>${t}</option>`).join('')}</select></div><div class="v3-actions">${button('verify-fault','✓ Analisar falha')}${button('commission-hint','Dica gradual','outline')}</div><div id="v3-fault-feedback" class="v3-feedback" aria-live="polite">${c.passed?'<span class="v3-ok">✓ Diagnóstico registrado corretamente.</span>':'Selecione uma hipótese e justifique sua escolha.'}</div>`)}
${card('Registro de evidências',`${textinput('meta.notes','Observações e ações corretivas propostas','Registre recomendações técnicas sem instruir intervenção energizada.',true)}<div class="v3-actions">${button('validate:commission','✓ Validar comissionamento')}${button('tab:economia','Analisar economia →','outline')}</div>`)}
</div></div>`);}
function renderEconomics(){const e=E.economicsCalc(project),s=E.solarCalc(project);return wrap('6 · Viabilidade técnica e econômica','Padrão 1.3 — justificar propostas com matemática financeira e hipóteses declaradas. Estimativa sem compensação regulatória real.',`
<div class="v3-two"><div class="v3-stack">
${card('Investimento e custos',`<div class="v3-form-grid">${input('economics.panelPrice','Preço por módulo','R$/un',0,100000,10)}${input('economics.inverterPrice','Inversor e componentes','R$',0,10000000,100)}${input('economics.installationPerWp','Instalação / potência','R$/Wp',0,50,.1)}${input('economics.engineering','Serviços de engenharia','R$',0,1000000,100)}${input('economics.extras','Outros custos','R$',0,1000000,100)}${input('economics.annualOM','Operação/manutenção','% invest./ano',0,30,.1)}${input('economics.recognized','Fração de energia valorizada','%',0,100,1,'Hipótese didática; não é regra de compensação.')}${input('economics.lifetime','Horizonte de análise','anos',1,40,1)}${input('site.tariff','Tarifa de referência','R$/kWh',.01,10,.01)}</div>`)}
${card('Riscos da estimativa',`<p>A análise não considera fluxo horário de consumo, sazonalidade meteorológica, degradação, reajustes, impostos, encargos, juros, financiamento, troca de inversor, demanda faturada nem regras reais de compensação.</p><p>Em unidades consumidoras com tarifa horária ou demanda contratada, o retorno exige modelo tarifário e perfil de carga adequados.</p>`)}
</div><div class="v3-stack">
${card('Indicadores econômicos',`<div class="v3-kpis">${metric('Investimento inicial',money(e.investment),'Equipamentos + serviço')}${metric('Energia valorizada',`${fmt(e.credited,1)} kWh/mês`,'Limitada ao consumo e fator didático','green')}${metric('Economia estimada',money(e.monthlySavings),'Por mês','orange')}${metric('Custo anual de O&M',money(e.annualOM),'Baseado no investimento')}${metric('Saldo líquido anual',money(e.annualNet),'Economia anual − O&M')}${metric('Retorno simples',e.payback===null?'Não calculável':`${fmt(e.payback,1)} anos`,'Sem desconto ou financiamento','green')}</div>${!e.valid?'<div class="v3-alert bad">A análise de economia tarifária está disponível apenas para o cenário on-grid e com entradas válidas. Para off-grid, utilize custos de geração substituída, autonomia e manutenção em um estudo específico.</div>':'<div class="v3-alert good">Estimativa econômica calculada; não é garantia de economia de fatura.</div>'}<div class="v3-actions">${button('validate:economics','✓ Validar viabilidade')}${button('tab:relatorio','Montar relatório →','outline')}</div>`)}
${card('Fluxo de caixa simplificado',`<p class="v3-fine">Série anual ilustrativa com investimento no ano zero e saldo anual constante. Não é Valor Presente Líquido (VPL).</p><div class="v3-bars">${Array.from({length:Math.min(10,e.horizon)},(_,idx)=>{const value=-e.investment+e.annualNet*(idx+1);const limit=Math.max(e.investment,Math.abs(-e.investment+e.annualNet*Math.min(10,e.horizon)),1);const abs=Math.min(100,Math.abs(value)/limit*100);return `<div class="v3-barrow"><span>Ano ${idx+1}</span><div><div class="${value>=0?'positive':'negative'}" style="width:${abs}%"></div></div><strong>${money(value)}</strong></div>`;}).join('')}</div><div class="v3-math"><code>Investimento = módulos × preço + inversor + (Wp × R$/Wp) + engenharia + extras</code><p>${fmt(s.modules,0)} × ${money(project.economics.panelPrice)} + demais parcelas = <b>${money(e.investment)}</b>.</p><code>Payback simples = investimento ÷ (12 × economia/mês − O&M anual)</code><p>Resultado: <b>${e.payback===null?'indefinido (saldo não positivo)':fmt(e.payback,2)+' anos'}</b>.</p></div>`)}
</div></div>`);}
function reportBody(){const a=E.assessment(project),d=a.solar,e=a.economics,c=a.site;const date=new Intl.DateTimeFormat('pt-BR',{dateStyle:'long'}).format(new Date());return `<article id="v3-report" class="v3-report" aria-label="Relatório técnico didático pronto para impressão">
<div class="v3-report-brand"><img src="${esc(document.querySelector('.senai-hub-identity img')?.getAttribute('src')||'assets/logo-senai-hub.webp')}" alt="Logo SENAI HUB"/><div><strong>ENERGYLAB PRO 3.0</strong><small>RELATÓRIO TÉCNICO — PROJETO DIDÁTICO</small></div></div>
<h2>Estudo preliminar de integração fotovoltaica</h2><div class="v3-report-meta"><span>Data: ${esc(date)}</span><span>Tipo: ${project.site.connection==='grid'?'Conectado à rede':'Isolado — conceitual'}</span><span>UC: Integração de Sistemas de Energias Renováveis · 16 h</span></div>
<h3>1. Caracterização do cliente</h3><p><b>Equipe / estudante:</b> ${esc(project.meta.student||'Não informado')}<br><b>Empreendimento:</b> ${esc(project.site.client)}<br><b>Local:</b> ${esc(project.site.city)}<br><b>Tensão/padrão declarado:</b> ${esc(project.site.supply)}<br><b>Consumo da fatura:</b> ${fmt(project.site.consumption,0)} kWh/mês; <b>cargas estimadas:</b> ${fmt(c.monthlyLoad,1)} kWh/mês; <b>potência conectada:</b> ${fmt(c.connectedKW,2)} kW.<br><b>Área:</b> ${fmt(project.site.roof,1)} m² total, ${fmt(project.site.usable,1)} m² úteis.</p>
<h3>2. Proposta de geração</h3><table><tbody><tr><th>Arranjo FV</th><td>${project.pv.series} módulos/string × ${project.pv.parallel} strings = ${d.modules} módulos de ${fmt(project.pv.wp,0)} Wp</td></tr><tr><th>Potência CC / CA</th><td>${fmt(d.dcWp/1000,2)} kWp / ${fmt(project.inverter.acKW,2)} kW</td></tr><tr><th>Área instalada</th><td>${fmt(d.area,1)} m²</td></tr><tr><th>Condições</th><td>HSP ${fmt(project.site.hsp,1)} h/dia; PR ${fmt(project.pv.pr,2)}; sombreamento ${fmt(project.site.shade,0)}%</td></tr><tr><th>Estimativa média</th><td>${fmt(d.dailyKWh,2)} kWh/dia; ${fmt(d.monthlyKWh,1)} kWh/mês</td></tr><tr><th>Voc no frio</th><td>${fmt(d.vocCold,1)} V; limite CC informado ${fmt(project.inverter.maxDC,0)} V</td></tr><tr><th>Vmp em célula quente</th><td>${fmt(d.vmpHot,1)} V; faixa MPPT ${fmt(project.inverter.mpptMin,0)}–${fmt(project.inverter.mpptMax,0)} V</td></tr><tr><th>Corrente por MPPT</th><td>Imp ${fmt(d.mpptImp,2)} A; Isc ${fmt(d.mpptIsc,2)} A</td></tr></tbody></table>
<h3>3. Avaliação econômica simplificada</h3><p><b>Investimento estimado:</b> ${money(e.investment)}. <b>Economia mensal ilustrativa:</b> ${money(e.monthlySavings)}. <b>O&M anual:</b> ${money(e.annualOM)}. <b>Retorno simples:</b> ${e.payback===null?'não calculável':fmt(e.payback,2)+' anos'}.</p>
<h3>4. Verificações e competências</h3><p><b>Levantamento:</b> ${a.goals.vistoria?'verificado':'pendente'}. <b>Dimensionamento:</b> ${a.goals.dimensionamento?'sem alertas críticos no modelo':'possui pendências'}. <b>Diagrama:</b> ${a.goals.diagrama?'registrado':'pendente'}. <b>Segurança:</b> ${a.safetyCount}/${E.safetyQuestions.length} itens. <b>Comissionamento:</b> ${a.goals.comissionamento?'registrado':'pendente'}. <b>Economia:</b> ${a.goals.economia?'calculada':'pendente'}.</p>
${a.issues.length?`<p><b>Pendências identificadas:</b> ${a.issues.map(esc).join('; ')}.</p>`:'<p><b>Alertas críticos do modelo:</b> não identificados nas entradas atuais.</p>'}
<h3>5. Documentação de conexão (conferência)</h3><p>${E.documentItems.filter(q=>project.docs[q.id]).map(q=>esc(q.text)).join('; ')||'Nenhum item conferido no exercício.'}. A obrigatoriedade depende do enquadramento e da concessionária.</p><h3>6. Fundamentação técnica / defesa do aluno</h3><p class="v3-report-notes">${esc(project.meta.notes||'Não preenchida.')}</p>
<h3>7. Premissas, limites e recomendações</h3><p>Este documento é um <b>exercício educacional</b>. HSP, coeficientes, tarifas, equipamentos e condições são ilustrativos. A energia mensal usa condições médias idealizadas: kWp × HSP × PR × (1 − sombreamento) × 30. Os coeficientes de tensão são aproximações lineares. Não há estudo estrutural, dimensionamento de cabos/proteções, avaliação de interferências, medições, análise tarifária completa, homologação ou verificação normativa. A proteção, operação e conexão real exigem projeto, normas vigentes, catálogos, estudo local e profissionais habilitados.</p>
<div class="v3-report-footer">EnergyLab PRO 3.0 · SENAI HUB · Relatório de aprendizagem · ${esc(date)} · Emitido localmente sem transmissão de dados</div>
</article>`;}
function renderReport(){const a=E.assessment(project),g=a.goals;return wrap('7 · Dossiê técnico e avaliação final','Situação de aprendizagem: entrega de um estudo preliminar defendido tecnicamente. Todas as informações permanecem no navegador.',`
<div class="v3-two v3-report-grid"><div class="v3-stack">
${card('Verificação da situação de aprendizagem',`<p>O cliente fictício solicita solução de geração elétrica segura, tecnicamente justificada e economicamente analisada. Confirme as evidências antes da entrega.</p><div class="v3-requirements">${[['vistoria','Levantamento e quadro de cargas','Padrão 1.1'],['dimensionamento','Dimensionamento e limites de equipamentos','Padrão 1.3'],['diagrama','Interpretação do diagrama','Padrão 1.2'],['seguranca','Checklist de segurança e sustentabilidade','Padrão 1.2'],['comissionamento','Interpretação de falha e documentação de testes','Padrão 1.2'],['economia','Avaliação da viabilidade','Padrão 1.3']].map(([k,t,cap])=>`<div class="v3-requirement ${g[k]?'ok':'pending'}"><span>${g[k]?'✓':'○'}</span><div><strong>${t}</strong><small>${cap}</small></div>${button('tab:'+k,'Revisar','outline')}</div>`).join('')}</div>`)}
${card('Defesa técnica da equipe',`${textinput('meta.student','Equipe / estudante','Nome opcional; evite dados pessoais reais em dispositivos compartilhados.')}${textinput('meta.notes','Justificativa e recomendações ao cliente','Explique o que dimensionou, os limites, a escolha dos equipamentos, riscos e próximos passos. Pelo menos 60 caracteres para registrar a entrega.',true)}<div class="v3-actions">${button('validate:delivery','✓ Registrar avaliação final')}${button('print','Imprimir / salvar em PDF','outline')}${button('download-report','↓ Exportar relatório HTML','quiet')}</div><p class="v3-fine">O PDF é criado pela opção “Salvar como PDF” da caixa de impressão do navegador. O relatório exportado pode ser aberto offline.</p>`)}
${card('Rubrica recomendada para o docente',`<div class="v3-rubric">${[['Levantamento e interpretação dos dados','15%'],['Cálculos e dimensionamento','25%'],['Documentação e conformidade','20%'],['Segurança e comissionamento','20%'],['Justificativa, cooperação e proatividade','20%']].map(([k,v])=>`<div><span>${k}</span><strong>${v}</strong></div>`).join('')}</div><p class="v3-fine">A plataforma registra evidências; a atribuição de notas e avaliação socioemocional são responsabilidade do docente. A aprovação não é automática.</p>`)}
</div><div class="v3-stack">${card('Prévia do relatório editável',`${reportBody()}`)}</div></div>`);}
function getPath(path){return path.split('.').reduce((a,k)=>a?.[k],project);}
function invalidate(group){const c=project.meta.completed||{};if(group==='site'){c.vistoria=false;c.dimensionamento=false;c.economia=false;project.diagramReviewed=false;}if(group==='pv'||group==='inverter'){c.dimensionamento=false;c.economia=false;project.diagramReviewed=false;}if(group==='economics')c.economia=false;if(group==='docs')c.relatorio=false;if(group==='safety')c.seguranca=false;if(group==='commission')c.comissionamento=false;c.relatorio=false;project.meta.evaluatedAt='';}
function setPath(path,val){if(!/^(site|pv|inverter|economics|meta|commission)\.[a-zA-Z]+$/.test(path))return false;const [head,key]=path.split('.');if(!Object.hasOwn(project[head],key))return false;project[head][key]=val;invalidate(head);save();return true;}
function setNumeric(el){const path=el.dataset.workfield;const value=Number(el.value),min=Number(el.min),max=Number(el.max);if(el.value.trim()===''||!Number.isFinite(value)||value<min||value>max){lastIssue=`${el.closest('.v3-field')?.querySelector('label')?.textContent||'Campo'}: informe valor entre ${min} e ${max}.`;render();return;}lastIssue='';setPath(path,value);render();}
function updateLoad(el){const l=project.loads.find(x=>x.id===el.dataset.load);if(!l)return;const k=el.dataset.loadprop;if(!['name','qty','w','h','days'].includes(k))return;if(k==='name'){l.name=el.value.slice(0,100);}else{const val=Number(el.value),max=k==='h'?24:k==='days'?31:k==='qty'?10000:1000000;if(el.value.trim()===''||!Number.isFinite(val)||val<0||val>max){lastIssue='Valor da carga inválido. Verifique o intervalo informado.';render();return;}l[k]=val;}lastIssue='';invalidate('site');save();render();}
function downloadable(name,content,mime){const b=new Blob([content],{type:mime});const url=URL.createObjectURL(b);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportJson(){downloadable('EnergyLab_PRO_3_0_projeto_uc16.json',JSON.stringify({...project,meta:{...project.meta,exportedAt:new Date().toISOString()}},null,2),'application/json;charset=utf-8');notify('Arquivo JSON exportado. Guarde o projeto para uso posterior.');}
function exportReportHtml(){const css=`body{font:15px/1.5 Arial,sans-serif;margin:32px auto;max-width:940px;color:#20304a;background:white}h2{font-size:25px}h3{border-bottom:1px solid #c8d7e9;padding-bottom:5px;margin-top:24px}.v3-report-brand{display:flex;justify-content:space-between;align-items:center;gap:20px}.v3-report-brand img{width:170px;max-height:65px;object-fit:contain}.v3-report-brand strong,.v3-report-brand small{display:block}.v3-report-meta{display:flex;gap:18px;flex-wrap:wrap;color:#55708c;font-size:12px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #c8d7e9;text-align:left;padding:7px}.v3-report-footer{margin-top:25px;border-top:1px solid #99aac6;padding-top:10px;font-size:11px;color:#596b85}button{display:none}`;
const html='<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>EnergyLab PRO — Relatório didático</title><style>'+css+'</style></head><body>'+reportBody()+'</body></html>';
const img=document.querySelector('.senai-hub-identity img')?.src||'assets/logo-senai-hub.webp';const complete=html.replace('src="assets/logo-senai-hub.webp"',`src="${img}"`);downloadable('EnergyLab_PRO_3_0_relatorio_didatico.html',complete,'text/html;charset=utf-8');notify('Relatório HTML offline exportado.');}
function checkFault(){const c=project.commission,q=E.faultCases[c.fault];c.attempts++;project.meta.completed.comissionamento=false;project.meta.completed.relatorio=false;if(c.answer===q.correct){c.passed=true;notify('Diagnóstico correto! Agora conclua os demais itens de comissionamento.');}else{c.passed=false;notify(c.attempts<2?'Ainda não. Analise o comportamento da medida e solicite uma dica.':`Reveja: ${q.hint}`);}save();render();}
function action(key){let a=E.assessment(project),d=a.solar;switch(true){
case key==='start':show('vistoria',true);return;
case key==='example':if(!confirm('Restaurar os dados do exercício? A vistoria, a avaliação e o progresso técnico serão apagados.'))return;project=E.defaults();save();show('trilha');notify('Exemplo didático restaurado.');return;
case key.startsWith('tab:'):show(key.slice(4),true);return;
case key==='addload':if(project.loads.length>=35)return notify('Máximo de 35 linhas didáticas.');project.loads.push({id:'l'+Date.now()+Math.round(Math.random()*1000),name:'Nova carga',qty:1,w:500,h:4,days:22});invalidate('site');save();render();return;
case key.startsWith('remove:'):project.loads=project.loads.filter(x=>x.id!==key.slice(7));invalidate('site');save();render();return;
case key==='validate:site':if(a.site.problems.length||!project.loads.length)return notify(a.site.problems.join(' ')||'Inclua ao menos uma carga.');project.meta.completed.vistoria=true;save();render();return notify('Levantamento didático validado. Confira dados de campo e fatura em projetos reais.');
case key==='validate:pv':if(!d.valid)return notify(`Corrija primeiro: ${d.errors[0]}`);project.meta.completed.dimensionamento=true;save();render();return notify('Dimensionamento registrado após verificação dos limites didáticos.');
case key==='apply-sim':if(!d.valid)return notify('Corrija os alertas do dimensionamento antes de aplicar ao simulador.');if(d.modules>80||project.inverter.acKW>20)return notify('O simulador básico aceita até 80 módulos e inversores de até 20 kW. Ajuste o cenário.');if(window.EnergyLabBridge){window.EnergyLabBridge.applyDesign({modules:d.modules,inverters:1,area:project.pv.area,acKW:project.inverter.acKW,shade:project.site.shade,panelEff:project.pv.wp/(project.pv.area*1000)*100,mode:project.site.connection,loadKW:a.site.connectedKW});window.EnergyLabBridge.goto('sim');notify('Arranjo e consumo de pico aplicados como cenário instantâneo aproximado. A estimativa anual da Oficina permanece independente.');}return;
case key==='mark-diagram':project.diagramReviewed=true;project.meta.completed.relatorio=false;save();render();notify('Interpretação do diagrama registrada.');return;
case key==='download-svg':{const svg=$('v3-singleline');const content='<?xml version="1.0" encoding="utf-8"?>\n'+new XMLSerializer().serializeToString(svg);downloadable('EnergyLab_PRO_3_0_diagrama_didatico.svg',content,'image/svg+xml;charset=utf-8');return;}
case key==='validate:safety':if(a.safetyCount<E.safetyQuestions.length)return notify(`Há ${E.safetyQuestions.length-a.safetyCount} item(ns) pendente(s).`);project.meta.completed.seguranca=true;save();render();return notify('Checklist didático concluído. Ainda requer validação profissional em obra real.');
case key==='verify-fault':checkFault();return;
case key==='commission-hint':{const q=E.faultCases[project.commission.fault];notify(project.commission.attempts<1?'Dica 1: analise se o problema afeta tensão, corrente ou polaridade.':'Dica 2: '+q.hint);return;}
case key==='hint:safety':{const el=$('v3-safety-hint');el.textContent='Mesmo sem alimentação da concessionária, módulos iluminados podem permanecer com tensão CC. Um plano seguro considera todas as fontes de energia.';return;}
case key==='validate:commission':if(!E.commissioningSteps.every(x=>project.commission.steps[x.id])||!project.commission.passed)return notify('Conclua os cinco itens documentais e identifique corretamente a falha simulada.');project.meta.completed.comissionamento=true;save();render();return notify('Comissionamento virtual registrado.');
case key==='validate:economics':if(!E.economicsCalc(project).valid)return notify('O estudo tarifário exige modo conectado à rede e parâmetros coerentes. Corrija os dados.');project.meta.completed.economia=true;save();render();return notify('Análise econômica registrada com as hipóteses declaradas.');
case key==='validate:delivery':{const missing=Object.entries(a.goals).filter(([k,v])=>k!=='relatorio'&&!v).map(([k])=>tabs[k][0]);if(missing.length)return notify('Ainda faltam evidências: '+missing.join('; ')+'.');if((project.meta.notes||'').trim().length<60)return notify('Inclua uma defesa técnica com pelo menos 60 caracteres, indicando justificativas, limitações e recomendações.');project.meta.completed.relatorio=true;project.meta.evaluatedAt=new Date().toISOString();save();render();notify('Entrega final registrada! A avaliação da equipe e a atribuição de nota permanecem a cargo do docente.');return;}
case key==='print':document.body.classList.add('v3-print-mode');window.print();setTimeout(()=>document.body.classList.remove('v3-print-mode'),1500);return;
case key==='download-report':exportReportHtml();return;
}}
function bind(){document.addEventListener('energylab:page',e=>{if(e.detail?.page==='oficina')render();});
const root=$('page-oficina');if(!root)return;
root.addEventListener('click',e=>{const tab=e.target.closest('[data-worktab]');if(tab){show(tab.dataset.worktab);return;}const b=e.target.closest('[data-workaction]');if(b)action(b.dataset.workaction);});
root.addEventListener('change',e=>{const el=e.target;
if(el.dataset.workfield){setNumeric(el);return;}
if(el.dataset.worktext){setPath(el.dataset.worktext,el.value.slice(0,900));render();return;}
if(el.dataset.workselect){const path=el.dataset.workselect;const v=el.value;setPath(path,v);if(path==='commission.fault'){project.commission.passed=false;project.commission.answer='';project.commission.attempts=0;save();}render();return;}
if(el.dataset.load){updateLoad(el);return;}
if(el.dataset.preset){const preset=E.panelPresets[el.value];if(preset){project.pv={...project.pv,...preset};invalidate('pv');save();render();}return;}
if(el.dataset.safety){project.safety[el.dataset.safety]=el.checked;invalidate('safety');save();render();return;}
if(el.dataset.doc){project.docs[el.dataset.doc]=el.checked;invalidate('docs');save();render();return;}
if(el.dataset.commission){project.commission.steps[el.dataset.commission]=el.checked;invalidate('commission');save();render();return;}
});
$('v3-export').addEventListener('click',exportJson);
$('v3-reset').addEventListener('click',()=>{if(!confirm('Reiniciar os dados e verificações da Oficina PRO neste navegador?'))return;project=E.defaults();save();show('trilha');});
window.addEventListener('afterprint',()=>document.body.classList.remove('v3-print-mode'));
window.EnergyLabProjectTest={getProject:()=>structuredClone(project),getAssessment:()=>E.assessment(project),set:(path,value)=>{setPath(path,value);render();},open:show,engine:E};
render();}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',bind);else bind();
})();
